        "absolute z-slider-range data-[orientation=horizontal]:h-full data-[orientation=vertical]:w-full",
        local.class,
      )}
      {...others}
    />
  );
};

type SliderThumbComponentProps<T extends ValidComponent = "span"> = PolymorphicProps<
